class ScoutAPIError(Exception):
    """
    Raised when there are problems with Scout API requests
    """
    pass


class ReportCalculationNotFinished(Exception):
    """
    Raised when report calculation didn't finish
    """
    pass


class ReportValidationFailed(Exception):
    """
    Raised when Scout report validation failed for checked KPIs and PMs counters
    """
    pass
